package com.creatio.autotest.testdata.models;

import lombok.Builder;
import lombok.Getter;

/**
 * Данные стадии «Информирование клиента» (Агро/Микро).
 * <p>
 * Специфика сегмента «Микро»: помимо согласия клиента заполняются две
 * мастер-страницы — идентификация клиента (мидл-контролер) и подписание
 * договора (ответственный).
 * <p>
 * «Мидл контролер» — не отдельная роль входа: это функциональная роль внутри
 * пользователя (им может быть ИКОК, ИКОК-ГО или кредитный эксперт), поэтому
 * здесь хранится только ФИО для выбора в поле, а не учётные данные.
 */
@Getter
@Builder
public class AgroClientNotificationData {

    /** Результат активности информирования (happy-path: «Клиент согласен»). */
    private final String clientAgreement;

    /** ФИО мидл-контролера — поле «Идентифицировал клиента». */
    private final String middleControllerName;

    /** ФИО пользователя ИКОК-ГО — поле «Ответственный за подписание». */
    private final String signingResponsible;
}